{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C61"],
      "claim": "Lefamulin, a polycyclic diterpenoid antibiotic, has an absolute oral bioavailability of 25.8% in healthy subjects, directly supporting F≥20% for a structurally related rigid terpenoid lactone.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "BMS-275183, a complex taxane diterpene ester, has a mean absolute oral bioavailability of 24% in humans, supporting F≥20% for the query's polycyclic lactone scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Tacrolimus, a complex macrocyclic lactone with numerous H-bond acceptors, shows oral bioavailability of 25% in pediatric liver transplant recipients, meeting the F≥20% threshold despite permeability liabilities.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C58"],
      "claim": "Amphotericin B has negligible oral bioavailability in humans, but this is driven by its large amphoteric polyene structure, poor solubility, and acid instability, which are not shared by the neutral, rigid query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "High-transfer experimental evidence predominantly supports F≥20%: structurally related terpenoid/lactone analogues (lefamulin ~25%, BMS-275183 ~24%, tacrolimus ~20-25%) meet the threshold, while the only strong low-F analogue (amphotericin B) has unique ionizable/instability liabilities not applicable to the query. The physicochemical low-permeability prior is overridden by this transferable experimental evidence.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule; prediction relies on transferable analogues.",
    "Amphotericin B's low-F evidence is mechanistically less applicable due to its amphoteric, high-MW, and acid-labile character, but its high transfer score adds uncertainty.",
    "The query's very low logD and high TPSA suggest a permeability risk that is not directly resolved by the available analogue data."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

